-- 种子数据：第一课
INSERT OR IGNORE INTO lessons (id, module, lesson_index, title, content_json) VALUES (1, '不被PUA', 1, '受害者叙事 vs 策略选择者叙事', '{"one_liner":"同样一件事，用不同的框架讲述，结果完全不同","concept":{"victim":"受害者叙事：事情发生在我身上，我是被动的、无奈的。讲出来的故事里，你是被命运安排的人。","strategist":"策略选择者叙事：我在每个节点做了当时我能做的最优选择。即使结果不完美，选择权始终在我手里。","key_insight":"两者讲的是完全同一段经历——区别只在于你怎么组织这些事实。"},"case":{"source":"菲森科技面试 · 2026年7月","question":"你的整个履历当中普遍工作时长很短，你对这个事情怎么评价？","interviewer":"藤真（菲森科技COO）","your_answer":"只能说接受吧…并不是我主动要去选择离开的…","what_he_heard":["只能接受 → 这个人觉得自己是受害者","并不是我主动要离开的 → 他没有职业选择的标准","沉默 → 他没有反思过这个问题"],"what_he_wanted":["每段经历都是我的主动选择 → 我是一个有标准的人","我来菲森也是基于同样的选择逻辑 → 这次选择是深思熟虑的","具体的归因 → 我在持续成长"],"deep_insight":"藤真问这个问题的真实目的不是让你解释为什么短——他是在测试你如何看待自己的过去。"},"exercise":{"question":"用「策略选择者」视角，重新描述你的短任期经历。","hint":"不用回避事实。同样的经历，换一个框架来组织。","placeholder":"我的第一份工作在易加油，当时我选择加入的原因是____，在那里我学会了____。当我意识到____之后，我主动选择离开，因为我想补____的能力…"},"next_preview":"识别你的受害者叙事触发模式"}');
